<?php
 namespace Pterodactyl\Models\Dezerx; use Illuminate\Support\Str; use Pterodactyl\Models\User; use Pterodactyl\Models\ApiKey; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Database\Eloquent\Relations\BelongsTo; class DiscordBot extends Model { protected $table = 'dezerx_discord_bots'; protected $guarded = ['id']; protected $hidden = ['token', 'client_secret']; protected $casts = [ 'user_id' => 'int', 'token' => 'encrypted', 'client_secret' => 'encrypted', 'owner_ids' => 'array', 'settings' => 'array', 'api_key_id' => 'int', 'commands_synced_at' => 'immutable_datetime', ]; protected static function booted(): void { static::creating(function (self $bot) { $bot->uuid = $bot->uuid ?: (string) Str::uuid(); }); } public function owner(): BelongsTo { return $this->belongsTo(User::class, 'user_id'); } public function apiKey(): BelongsTo { return $this->belongsTo(ApiKey::class, 'api_key_id'); } public function alerts(): HasMany { return $this->hasMany(DiscordBotAlert::class, 'bot_id'); } public function ownedBy(string $discordId): bool { return $discordId !== '' && in_array($discordId, array_map('strval', (array) ($this->owner_ids ?? [])), true); } public function canOAuth(): bool { return trim((string) $this->client_secret) !== ''; } public function isGlobal(): bool { return $this->user_id === null; } public function avatarUrl(): string { if ($this->avatar === null || $this->avatar === '') { return 'https://cdn.discordapp.com/embed/avatars/0.png'; } return sprintf('https://cdn.discordapp.com/app-icons/%s/%s.png?size=256', $this->application_id, $this->avatar); } } 